      (4, 'INDUCER', 'SERVICE', 1, 'PROPOSED', 'If the pressure switch fault persists')) x(n, code, kind, qty, st, grp)
      join pm.price_book_items pb on pb.location_id = c_loc and pb.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 4 then raise exception 'DEMO %: work order lines matched % of 4 price book codes', v_key, v_n; end if;
