    insert into pm.estimates (job_id, title, retainage_pct, valid_until, notes)
      values (v_job, 'Accepted — 96% two-stage furnace + 16 SEER2 AC', null, current_date + 21, 'Signed in the home; 40% deposit, balance at completion.') returning id into v_est;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, qty, uom, unit_cost_cents, unit_price_cents, cost_cents, amount_cents, is_allowance)
    select v_est, x.n, x.n, c.id, x.d, x.qty::numeric, x.uom, x.uc::bigint, x.up::bigint, x.cost::bigint, x.amt::bigint, x.allow
      from (values
      (1, 'INS-EQP', '96% AFUE two-stage furnace, 80k BTU, variable-speed ECM blower', 1, 'EA', 214000, 438000, 214000, 438000, false),
      (2, 'INS-EQP', '3-ton 16 SEER2 AC condenser and cased coil (R-454B)', 1, 'EA', 286000, 562000, 286000, 562000, false),
      (3, 'INS-MAT', 'Line set, pad, disconnect, whip, condensate pump and flue kit', 1, 'LS', 64000, 118000, 64000, 118000, false),
      (4, 'INS-LAB', 'Install labor — 2-tech crew, 1 day', 1, 'LS', 128000, 165000, 128000, 165000, false),
      (5, 'INS-ELE', 'New 30A condenser circuit (Capital City Electric)', 1, 'LS', 38000, 52000, 38000, 52000, false),
      (6, 'INS-PRM', 'City of Johnston mechanical permit', 1, 'EA', 18500, 18500, 18500, 18500, false),
      (7, 'INS-DSP', 'Recover refrigerant, haul away and recycle old equipment', 1, 'EA', 6500, 14500, 6500, 14500, false),
      (8, 'INS-COM', 'Comfort advisor commission', 1, 'EA', 61000, 0, 61000, 0, false)) x(n, code, d, qty, uom, uc, up, cost, amt, allow)
      left join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 8 or exists (select 1 from pm.estimate_lines l where l.estimate_id = v_est and l.cost_code_id is null and l.cost_cents <> 0) then
      raise exception 'DEMO %: estimate lines did not resolve their cost codes', v_key;
    end if;
    perform pm.send_estimate(v_est);
    v_j := pm.accept_estimate(v_est);
    perform pm.request_deposit(v_job, 547200, 'Deposit — 40% at signing');
    v_fail := pm.transition_stage(v_job, 'sold');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'sold', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'equipment_permit');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'equipment_permit', v_fail; end if;
    insert into pm.commitments (job_id, vendor_id, commitment_type, title, description, retainage_pct)
      values (v_job, v_v_midwesthvac, 'PO', 'Equipment for Ortega replacement', null, 0) returning id into v_cmt;
    insert into pm.commitment_lines (commitment_id, line_no, cost_code_id, description, amount_cents)
    select v_cmt, x.n, c.id, x.d, x.a::bigint
      from (values
      (1, 'INS-EQP', '80k two-stage furnace', 214000),
      (2, 'INS-EQP', '3-ton AC condenser + cased coil, R-454B', 286000),
      (3, 'INS-MAT', 'Line set, pad, disconnect, whip, flue kit', 64000)) x(n, code, d, a)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 3 then raise exception 'DEMO %: commitment lines matched % of 3 cost codes', v_key, v_n; end if;
    v_wo := pm.create_work_order(p_job => v_job, p_kind => 'INSTALL', p_summary => 'Install furnace, AC, coil and line set', p_priority => 2,
      p_asset => v_a_ortega, p_requested_start => ((v_tue) + time '07:30') at time zone 'America/Chicago', p_requested_end => ((v_tue) + time '16:30') at time zone 'America/Chicago', p_estimated_minutes => 540,
      p_promised_on => v_tue);
    perform pm.schedule_work_order(v_wo, ((v_tue) + time '07:30') at time zone 'America/Chicago', ((v_tue) + time '16:30') at time zone 'America/Chicago', array[v_tech]);
    insert into pm.tasks (job_id, title, status, is_milestone, start_on, due_on, duration_days, pct_complete, sort, completed_at, assignee_user_id, assignee_employee_id)
    select v_job, x.t, x.st, x.ms, current_date + x.s, current_date + x.d, x.d - x.s, x.pct::numeric, x.n,
           case when x.st = 'DONE' then now() end, case when x.who = 'admin' then v_admin end, case when x.who = 'tech' then v_tech end
      from (values
      (1, 'Load calculation (Manual J)', 'DONE', false, -4, -4, 1, 'tech'),
      (2, 'Order equipment from Midwest HVAC Supply', 'IN_PROGRESS', false, -1, 1, 0.5, 'admin'),
      (3, 'Pull mechanical permit (City of Johnston)', 'DONE', false, -1, -1, 1, null),
      (4, 'Install day', 'TODO', false, 6, 6, null, 'tech'),
      (5, 'City inspection', 'TODO', true, 9, 9, null, null),
      (6, 'Register warranty and offer Comfort Club', 'TODO', false, 10, 10, null, null)) x(n, t, st, ms, s, d, pct, who);
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- atc-clive-dental-rtu: SAMPLE — RTU repair completed yesterday, price-book ticket ready to invoice
  -- ------------------------------------------------------------------------
  v_key := 'atc-clive-dental-rtu';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'service_call', 'Clive Family Dental — RTU-1 not cooling', v_c_clivedental, null, true,
      jsonb_build_object('_demo', v_key, 'business_unit', 'hvac_service', 'campaign', 'Existing customer'));
    update pm.projects set site_address_line1 = '1550 NW 114th St', site_city = 'Clive', site_state = 'IA', site_zip = '50325',
           planned_start = current_date + -1, planned_finish = current_date + -1,
           pm_user_id = v_admin
     where job_id = v_job;
    v_fail := pm.transition_stage(v_job, 'scheduled');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'scheduled', v_fail; end if;
    v_wo := pm.create_work_order(p_job => v_job, p_kind => 'SERVICE', p_summary => 'RTU-1 not cooling — operatories at 79°F', p_priority => 2,
      p_asset => v_a_clive, p_requested_start => ((current_date - 1) + time '13:00') at time zone 'America/Chicago', p_requested_end => ((current_date - 1) + time '17:00') at time zone 'America/Chicago',
      p_estimated_minutes => 120, p_complaint => 'Front office says the patient rooms are warm since lunch.', p_ext => jsonb_build_object('arrival_window', '12-4'));
    perform pm.schedule_work_order(v_wo, ((current_date - 1) + time '14:00') at time zone 'America/Chicago', ((current_date - 1) + time '16:00') at time zone 'America/Chicago', array[v_tech]);
    v_fail := pm.transition_stage(v_job, 'working');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'working', v_fail; end if;
    insert into pm.work_order_lines (work_order_id, sort, kind, price_book_item_id, qty, status, option_group)
    select v_wo, x.n, x.kind, pb.id, x.qty::numeric, x.st, x.grp
      from (values
      (1, 'DIAG', 'SERVICE', 1, 'APPROVED', null),
      (2, 'CAP-DUAL', 'SERVICE', 1, 'APPROVED', null),
      (3, 'CONT-1P', 'SERVICE', 1, 'APPROVED', null),
      (4, 'REF-410A', 'PART', 2, 'APPROVED', null),
      (5, 'COND-DRAIN', 'SERVICE', 1, 'APPROVED', null)) x(n, code, kind, qty, st, grp)
      join pm.price_book_items pb on pb.location_id = c_loc and pb.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 5 then raise exception 'DEMO %: work order lines matched % of 5 price book codes', v_key, v_n; end if;
    perform pm.complete_work_order(v_wo, 'FIXED', 'Replaced failed 45/5 dual run capacitor and pitted contactor; added 2 lb R-410A; cleared condensate line. Supply air 56°F, delta-T 19°F.');
    v_fail := pm.transition_stage(v_job, 'completed');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'completed', v_fail; end if;
    insert into pm.time_entries (job_id, employee_id, work_date, hours, pay_type, cost_code_id, notes, approval_state, work_order_id)
    select v_job, v_tech, current_date + x.day, x.h::numeric, x.pay, c.id, x.notes, 'SUBMITTED', x.wo::uuid
      from (values
      (-1, 1.75, 'REG', 'SVC-LAB', 'RTU-1 diagnosis and repair', v_wo::text)) x(day, h, pay, code, notes, wo)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    perform pm.set_contract(v_job, 101600);
    insert into pm.billing_requests (job_id, billing_type, billing_subtype, occurred_on, memo)
      values (v_job, 'MILESTONE', 'FIXED', current_date, 'Service ticket — RTU-1 repair (flat rate)') returning id into v_bill;
    insert into pm.billing_request_lines (billing_request_id, line_no, sort, description, amount_cents)
    select v_bill, l.sort, l.sort, l.description, l.amount_cents from pm.work_order_lines l where l.work_order_id = v_wo and l.status = 'APPROVED';
    n_jobs := n_jobs + 1;
  end if;


  -- ---- 6. summary ----
  raise notice 'DEMO ATC: ran as %; field tech %; pack % (%); this run created % job(s), % customer(s), % vendor(s)',
    v_admin_label, v_tech_label, c_pack, case when v_applied then 'applied now' else 'already installed' end, n_jobs, n_cust, n_vend;
  raise notice 'DEMO ATC totals: % demo jobs (% sample, % real); % tasks; % budget lines; % estimates (% accepted); % change orders; % commitments; % work orders (% dispatched); % billing requests; % deposit requests; % selections; % assets; % agreements; % time entries; % daily logs; % Books events from demo jobs',
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo' and p.is_sample),
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo' and not p.is_sample),
    (select count(*) from pm.tasks t join pm.projects p on p.job_id = t.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.budget_lines l join pm.budgets b on b.id = l.budget_id join pm.projects p on p.job_id = b.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.estimates e where e.location_id = c_loc),
    (select count(*) from pm.estimates e where e.location_id = c_loc and e.status = 'ACCEPTED'),
    (select count(*) from pm.change_orders x join pm.projects p on p.job_id = x.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.commitments x where x.location_id = c_loc),
    (select count(*) from pm.work_orders w where w.location_id = c_loc),
    (select count(distinct d.work_order_id) from pm.dispatch_assignments d join pm.work_orders w on w.id = d.work_order_id where w.location_id = c_loc and d.status <> 'CANCELLED'),
    (select count(*) from pm.billing_requests r where r.location_id = c_loc),
    (select count(*) from pm.deposit_requests r where r.location_id = c_loc),
    (select count(*) from pm.selections s join pm.projects p on p.job_id = s.job_id where p.location_id = c_loc),
    (select count(*) from pm.assets a where a.location_id = c_loc),
    (select count(*) from pm.service_agreements a where a.location_id = c_loc),
    (select count(*) from pm.time_entries t join pm.projects p on p.job_id = t.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.field_logs l join pm.projects p on p.job_id = l.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from core.events e where e.org_id = c_org and e.source_module = 'PROJECTS'
        and e.payload ->> 'job_id' in (select p.job_id::text from pm.projects p where p.location_id = c_loc and p.ext ? '_demo'));
end
$seed$;
